// ------------------------------------------------------------------------------------------
// §21.17 dashboard state consistency  /  §21.18 Unity state consistency
// ------------------------------------------------------------------------------------------

describe("state consistency", () => {
  it("dashboard panels agree with each other on the same frame's values", async () => {
    render(<App />);
    const socket = MockWebSocket.latest();
    act(() => socket.emitOpen());
    act(() => socket.emitMessage(REAL_CRITICAL_FRAME_MESSAGE));

    const table = screen.getByTestId("tracked-objects-table");
    await waitFor(() => expect(within(table).getByText("#track-1")).toBeInTheDocument());
    // Detected Objects TTC, Safety Min TTC, and the Critical Object breakdown all read the SAME
    // wire value (0.8758 -> "0.9 s") -- no panel recomputes it.
    expect(within(table).getByText("0.9 s")).toBeInTheDocument();
    const safety = screen.getByTestId("safety-panel");
    expect(within(safety).getByText("Min TTC", { selector: ".stat-label" }).closest(".stat-tile")!.textContent).toContain("0.9 s");
    expect(within(safety).getByText(/TTC: 0.9 s/)).toBeInTheDocument();
  });

  it("Unity consistency: the wire fields Unity parses equal the ones the dashboard shows (same message)", () => {
    // Dashboard and Unity are independent TCP clients of the SAME PerceptionStreamServer.publish()
    // output. This asserts the single wire message carries ONE consistent value per field, so
    // "Dashboard track_id == Unity track_id" etc. holds by construction (Unity does no perception).
    const d = HW.data;
    const obj = d.objects[0];
    const tracked = d.tracked_objects![0];
    const result = d.risk!.results[0];
    expect(tracked.track_id).toBe(obj.track_id);
    expect(result.track_id).toBe(obj.track_id);
    expect(tracked.classification).toBe(obj.classification);
    expect(tracked.distance).toBe(obj.distance);
    expect(tracked.ttc).toBe(result.ttc);
    expect(tracked.risk).toBe(result.risk_level);
    expect(d.risk!.overall_risk).toBe(tracked.risk);
    expect(d.clearance!.min_direction).toBe("left");
  });
});

// ------------------------------------------------------------------------------------------
// §12 update rate -- real, never a fixed constant
// ------------------------------------------------------------------------------------------

describe("update rate is measured, never a fixed constant", () => {
  it("shows the Edge measured_scan_rate_hz when present", async () => {
    render(<App />);
    const socket = MockWebSocket.latest();
    act(() => socket.emitOpen());
    act(() => socket.emitMessage(REAL_CRITICAL_FRAME_MESSAGE)); // performance_metrics.measured_scan_rate_hz = 10.0
    const liveData = screen.getByTestId("live-data-panel");
    await waitFor(() =>
      expect(within(liveData).getByText("Scan Rate").closest(".stat-tile")!.textContent).toContain("10.0 Hz"),
    );
  });

  it("falls back to this tab's own frames/elapsed when the Edge rate is absent -- not a hardcoded 10 Hz", () => {
    const nowSpy = vi.spyOn(Date, "now");
    nowSpy.mockReturnValue(1_000_000_000_000);
    render(<App />);
    const socket = MockWebSocket.latest();
    act(() => socket.emitOpen());

    const noRate = (seq: number) => ({
      ...HW,
      frame_id: seq,
      data: {
        ...HW.data,
        sequence_number: seq,
        performance_metrics: { pipeline_processing_ms: 5, measured_scan_interval_s: null, measured_scan_rate_hz: null, scans_processed: seq + 1 },
      },
    });

    nowSpy.mockReturnValue(1_000_000_000_000);
    act(() => socket.emitMessage(noRate(0)));
    nowSpy.mockReturnValue(1_000_000_000_250); // +250 ms
    act(() => socket.emitMessage(noRate(1)));
    nowSpy.mockReturnValue(1_000_000_000_500); // +250 ms -> 2 frames over 0.5 s -> 4.0 Hz
    act(() => socket.emitMessage(noRate(2)));

    const txt = within(screen.getByTestId("live-data-panel")).getByText("Scan Rate").closest(".stat-tile")!.textContent!;
    expect(txt).toMatch(/\d\.\d Hz/);        // a real measured figure
    expect(txt).not.toContain("target");     // NOT the configured-target fallback
    expect(txt).toContain("4.0 Hz");         // (count-1)/elapsed = 2 / 0.5 s
    nowSpy.mockRestore();
  });
});

// ------------------------------------------------------------------------------------------
// §14 Event Timeline -- connection events from real observed transitions
// ------------------------------------------------------------------------------------------

describe("Event Timeline includes connection events from real transitions", () => {
  it("'Data stream started' appears once a frame arrives; wire events still shown", async () => {
    render(<App />);
    const socket = MockWebSocket.latest();
    act(() => socket.emitOpen());
    act(() => socket.emitMessage(REAL_SCENARIO_SWITCH_FRAME_MESSAGE)); // carries 2 track_created events

    const timeline = screen.getByTestId("event-timeline-panel");
    await waitFor(() => expect(within(timeline).getByText(/Data stream started/)).toBeInTheDocument());
    expect(within(timeline).getAllByText(/Track Created/).length).toBeGreaterThan(0);
  });

  it("'Connection lost' appears when the socket closes", () => {
    vi.useFakeTimers();
    render(<App />);
    const socket = MockWebSocket.latest();
    act(() => socket.emitOpen());
    act(() => socket.emitMessage(REAL_CRITICAL_FRAME_MESSAGE));
    act(() => socket.close());
    const timeline = screen.getByTestId("event-timeline-panel");
    expect(within(timeline).getByText(/Connection lost/)).toBeInTheDocument();
  });
});
